/*
 * A164905  Primes from composite numbers by prefixing with 1.
 * https://oeis.org/A164905
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = the n‑th prime obtained by prefixing a 1 to successive
 *            composite numbers (in increasing order). The sequence is
 *            generated by scanning the composite integers c = 4, 6, 8, …; for
 *            each c produce x = 10^{digits(c)} + c; if x is prime, it is the
 *            next term of the sequence
 * Range:     u8 n <= 11, u16 n <= 44, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   digits, is_prime, is_prime_big, pow10, seq_alloc_array,
 *            seq_free_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* ------------------------------------------------------------------- */
/* Required utilities ------------------------------------------------- */
#include <stdbool.h>
#include <stdlib.h>
/* predicates and helpers used by the implementation                     */
#include "../utils/is_prime.h"        /* bool is_prime(idx_t)          */
#include "../utils/is_prime_big.h"   /* bool is_prime_big(seq_t)      */
#include "../utils/digits.h"         /* idx_t digits(idx_t)           */
#include "../utils/pow10.h"          /* seq_t pow10(seq_t)            */
#include "../utils/seq_alloc_array.h"/* seq_t *seq_alloc_array(size_t)*/
#include "../utils/seq_free_array.h" /* void seq_free_array(seq_t*)   */
/* ------------------------------------------------------------------- */

static const size_t INITIAL_CAP = 16;

seq_t a(idx_t n)
{
    /* static cache and state variables */
    static seq_t *cache  = NULL;
    static size_t cache_len = 0;   /* number of cached terms    */
    static size_t cache_cap = 0;   /* allocated capacity        */
    static idx_t next_c = 4;       /* first composite number    */

    if (n == 0)
        return (seq_t)0;           /* undefined for offset 0    */

    /* generate terms until we have at least n values in the cache */
    while (cache_len < n) {
        idx_t c = next_c++;

        /* skip prime integers */
        if (is_prime(c))
            continue;

        /* form the candidate by prefixing 1 */
        idx_t d   = digits(c);
        seq_t x   = pow10(d) + (seq_t)c;

        if (is_prime_big(x)) {
            /* grow the cache if necessary */
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap << 1 : INITIAL_CAP;
                seq_t *tmp = seq_alloc_array(new_cap);
                for (size_t i = 0; i < cache_len; ++i)
                    tmp[i] = cache[i];
                if (cache)
                    seq_free_array(cache);
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = x;
        }
    }

    return cache[n - 1];
}
